-- Flow: SQ_RAW_SUPPLIES -> SQ_RAW_PRODUCTS1 -> JNR_SUPPLIES_PRODUCTS -> EXP_SUPPLIES -> STG_SUPPLIES

with

sq_raw_supplies as (
    -- SQ_RAW_SUPPLIES (Source Qualifier): reads RAW_SUPPLIES
    select
        cast(id as varchar) as id,
        cast(name as varchar) as name,
        cast(cost as double) as cost,
        cast(perishable as varchar) as perishable,
        cast(sku as varchar) as sku
    from {{ source('raw', 'raw_supplies') }}
),

sq_raw_products1 as (
    -- SQ_RAW_PRODUCTS1 (Source Qualifier): reads RAW_PRODUCTS
    select
        cast(sku as varchar) as sku,
        cast(name as varchar) as name,
        cast(type as varchar) as type,
        cast(price as double) as price,
        cast(description as varchar) as description
    from {{ source('raw', 'raw_products') }}
),

jnr_supplies_products as (
    -- JNR_SUPPLIES_PRODUCTS (Joiner, Normal Join): SKU1 = SKU
    select
        detail.id as id,
        detail.name as name,
        detail.cost as cost,
        detail.perishable as perishable,
        detail.sku as sku,
        master.sku as sku1
    from sq_raw_supplies as detail
    inner join sq_raw_products1 as master
        on (master.sku = detail.sku)
),

exp_supplies as (
    -- EXP_SUPPLIES (Expression)
    select
        id as supply_id,
        name as supply_name,
        cost as supply_cost_cents,
        (cost / 100) as supply_cost,
        case when ((perishable = 'Y') or (perishable = '1')) then 1 else 0 end as is_perishable,
        sku as product_id
    from jnr_supplies_products
),

final as (
    -- STG_SUPPLIES (Target STG_SUPPLIES): cast to the target column types
    select
        cast(supply_id as varchar) as supply_id,
        cast(supply_name as varchar) as supply_name,
        cast(supply_cost_cents as decimal(12, 2)) as supply_cost_cents,
        cast(supply_cost as decimal(12, 2)) as supply_cost,
        cast(is_perishable as decimal(1, 0)) as is_perishable,
        cast(product_id as varchar) as product_id
    from exp_supplies
)

select * from final
